<?php
namespace App\Services;
use App\Models\{Business,User,BankStatementLine,SupplierPaymentSchedule,SupplierPayment,SupplierInvoice,Supplier,SupplierOperation,ExpensePayment};
use App\Exceptions\ApiException;
use App\Support\{Money,ExactMath};
use App\Tenancy\TenantContext;
use Illuminate\Support\Facades\DB;
use Illuminate\Auth\Access\AuthorizationException;
class BankReconciliationService {
 public function __construct(private FinancialActorService $actors,private TenantContext $context){}
 private function actor(User $original):User {$actor=$this->actors->lock($original,'manage_products');if(!$actor->hasRole('owner'))throw new AuthorizationException;Business::whereKey($this->context->requireId())->where('is_active',true)->lockForUpdate()->firstOrFail();return $actor;}
 private function target(string $class,string $id){$row=(new $class)->resolveRouteBindingQuery($class::query(),$id)->lockForUpdate()->first();if(!$row)throw new ApiException('NOT_FOUND','Record not found.',404);return $row;}
 private function line(BankStatementLine $line):array{return ['id'=>$line->publicId(),'account'=>$line->account,'booked_on'=>$line->booked_on->toDateString(),'direction'=>$line->direction,'amount'=>$line->amount,'reference'=>$line->reference,'payment_type'=>$line->matched_type,'payment_id'=>$line->matched_id?($line->matched_type==='supplier'?SupplierPayment::findOrFail($line->matched_id):ExpensePayment::findOrFail($line->matched_id))->publicId():null];}
 private function schedule(SupplierPaymentSchedule $row):array {$invoice=SupplierInvoice::findOrFail($row->invoice_id);return ['id'=>$row->publicId(),'invoice_id'=>$invoice->publicId(),'supplier_name'=>Supplier::findOrFail($invoice->supplier_id)->name,'invoice_reference'=>$invoice->invoice_reference,'due_on'=>$row->due_on->toDateString(),'amount'=>$row->amount,'remaining_amount'=>$invoice->remaining_amount,'status'=>$row->status,'overdue'=>$row->status==='scheduled'&&$invoice->remaining_amount>0&&$row->due_on->toDateString()<now('Africa/Dar_es_Salaam')->toDateString()];}
 public function index(User $original):array {return DB::transaction(function()use($original){$this->actor($original);$payments=[];foreach(['supplier'=>SupplierPayment::class,'expense'=>ExpensePayment::class] as $type=>$class)foreach($class::where('source','bank')->orderByDesc('id')->get() as $p){$direction=$type==='expense'&&$p->kind==='refund'?'credit':'debit';$payments[]=['id'=>$p->publicId(),'type'=>$type,'amount'=>$p->amount,'direction'=>$direction,'paid_on'=>$p->paid_on->toDateString(),'reference'=>$p->reference,'matched'=>BankStatementLine::where('matched_type',$type)->where('matched_id',$p->id)->exists()];}return ['lines'=>BankStatementLine::orderByDesc('id')->get()->map(fn($l)=>$this->line($l))->all(),'payments'=>$payments,'schedules'=>SupplierPaymentSchedule::orderBy('due_on')->get()->map(fn($s)=>$this->schedule($s))->all(),'external_transfer_executed'=>false];},3);}
 public function commit(User $original,string $action,array $input):array {return DB::transaction(function()use($original,$action,$input){$actor=$this->actor($original);$key=strtolower($input['operation_id']);$hash=SupervisorApprovalService::snapshotHash(['bank_action'=>$action,'input'=>$input]);$existing=SupplierOperation::where('operation_id',$key)->lockForUpdate()->first();if($existing){if((int)$existing->actor_id!==(int)$actor->id||(int)$existing->device_id!==(int)$actor->currentAccessToken()->device_id||!hash_equals($hash,$existing->request_fingerprint))throw new ApiException('OPERATION_ID_REUSED','Retry the original operation details.',409);return [...$existing->result,'replayed'=>true];}
  if($action==='statement'){$identity=hash_hmac('sha256',strtolower(trim($input['account'])).'|'.strtolower(trim($input['reference'])),config('app.key'));if(BankStatementLine::where('identity_hash',$identity)->exists())throw new ApiException('REFERENCE_ALREADY_RECORDED','This account statement reference is already recorded.',409);$row=BankStatementLine::create(['actor_id'=>$actor->id,'account'=>trim($input['account']),'booked_on'=>$input['booked_on'],'direction'=>$input['direction'],'amount'=>Money::amount($input['amount']),'reference'=>trim($input['reference']),'identity_hash'=>$identity]);$result=['line'=>$this->line($row)];}
  elseif($action==='match'){$row=$this->target(BankStatementLine::class,$input['line_id']);$type=$input['payment_type'];$p=$this->target($type==='supplier'?SupplierPayment::class:ExpensePayment::class,$input['payment_id']);$direction=$type==='expense'&&$p->kind==='refund'?'credit':'debit';if($row->matched_id||BankStatementLine::where('matched_type',$type)->where('matched_id',$p->id)->exists())throw new ApiException('BANK_ALREADY_MATCHED','Statement or payment is already matched.',409);if($p->source!=='bank'||$p->amount!==$row->amount||$direction!==$row->direction)throw new ApiException('BANK_MATCH_MISMATCH','Match a completed bank payment with the exact amount and direction.',422);$row->matched_type=$type;$row->matched_id=$p->id;$row->save();$result=['line'=>$this->line($row)];}
  elseif($action==='schedule'){$invoice=$this->target(SupplierInvoice::class,$input['invoice_id']);$amount=Money::amount($input['amount']);$scheduled=0;foreach(SupplierPaymentSchedule::where('invoice_id',$invoice->id)->where('status','scheduled')->lockForUpdate()->get() as $s)$scheduled=Money::amount(ExactMath::add($scheduled,$s->amount));if($amount<1||ExactMath::add($scheduled,$amount)>$invoice->remaining_amount)throw new ApiException('PAYABLE_CHANGED','Scheduled amounts exceed the currently unpaid invoice. Cancel stale plans first.',409);$row=SupplierPaymentSchedule::create(['actor_id'=>$actor->id,'invoice_id'=>$invoice->id,'due_on'=>$input['due_on'],'amount'=>$amount]);$result=['schedule'=>$this->schedule($row)];}
  elseif($action==='cancel'){$row=$this->target(SupplierPaymentSchedule::class,$input['schedule_id']);$row->status='cancelled';$row->save();$result=['schedule'=>$this->schedule($row)];}
  else throw new ApiException('VALIDATION_ERROR','Unsupported action.',422);
  $result['external_transfer_executed']=false;SupplierOperation::create(['actor_id'=>$actor->id,'device_id'=>$actor->currentAccessToken()->device_id,'operation_id'=>$key,'request_fingerprint'=>$hash,'action'=>'bank_'.$action,'result'=>$result]);activity()->causedBy($actor)->event('bank_'.$action)->withProperties(['business_id'=>$this->context->requireId(),'operation_id'=>$key,'device_id'=>$actor->currentAccessToken()->device_id])->log('Banking and supplier planning operation');return [...$result,'replayed'=>false];},3);}
 public function prices(User $original):array {return DB::transaction(function()use($original){$this->actor($original);$groups=[];foreach(SupplierInvoice::orderByDesc('invoice_date')->orderByDesc('id')->get() as $invoice)foreach($invoice->lines as $line){$key=$line['product_id'].'|'.$line['quantity_type'].'|'.$line['unit'];if(count($groups[$key]['receipts']??[])>=3)continue;$groups[$key]??=['product_id'=>$line['product_id'],'name'=>$line['name'],'unit'=>$line['unit'],'quantity_type'=>$line['quantity_type'],'receipts'=>[]];$groups[$key]['receipts'][]=['supplier_name'=>Supplier::findOrFail($invoice->supplier_id)->name,'invoice_id'=>$invoice->publicId(),'invoice_date'=>$invoice->invoice_date->toDateString(),'cost_price'=>$line['cost_price'],'base_qty'=>$line['base_qty']];}return ['products'=>array_values($groups),'basis'=>'TSh per original base item or kilogram; historical received prices'];},3);}
}

